REVOKE ALL ON FUNCTION public.store_income_category_suggestion(uuid,uuid,text,text) FROM PUBLIC, anon, authenticated, service_role;
COMMENT ON FUNCTION public.store_income_category_suggestion(uuid,uuid,text,text) IS 'Deprecated. Disabled: AI suggestions are only recorded by the authenticated server after provider validation.';
CREATE OR REPLACE FUNCTION public.store_income_category_suggestion(_record_id uuid, _actor_id uuid, _category_id uuid, _confidence text, _explanation text) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path = public, pg_temp AS $$ DECLARE r public.society_income_records%ROWTYPE; rev uuid; BEGIN SELECT * INTO r FROM public.society_income_records WHERE id = _record_id FOR UPDATE; IF NOT FOUND OR _actor_id IS NULL OR NOT public.is_society_admin_for(_actor_id, r.society_id) THEN RETURN jsonb_build_object('status','not_found'); END IF; IF NOT public.is_non_member_income_enabled_internal(r.society_id) THEN RETURN jsonb_build_object('status','plan_required'); END IF; IF r.verification_status <> 'pending' OR r.category_confirmed_at IS NOT NULL THEN RETURN jsonb_build_object('status','already_processed'); END IF; IF _confidence NOT IN ('high','medium') OR _explanation IS NULL OR length(_explanation) NOT BETWEEN 10 AND 220 OR _explanation ~* '(<|>|https?://|[a-f0-9]{8}-[a-f0-9]{4}-[a-f0-9]{4}-[a-f0-9]{4}-[a-f0-9]{12})' OR NOT EXISTS (SELECT 1 FROM public.society_income_categories c WHERE c.id = _category_id AND c.society_id = r.society_id AND c.is_active) THEN RETURN jsonb_build_object('status','invalid_input'); END IF; rev := gen_random_uuid(); UPDATE public.society_income_records SET suggested_category_id = _category_id, suggestion_confidence = _confidence, suggestion_explanation = _explanation, suggestion_revision = rev, suggested_at = now() WHERE id = r.id; INSERT INTO public.audit_log(actor_id, action, target_table, target_id, society_id, metadata) VALUES (_actor_id, 'income_record.category_suggested', 'society_income_records', r.id::text, r.society_id, jsonb_build_object('category_id',_category_id,'confidence',_confidence,'revision',rev)); RETURN jsonb_build_object('status','suggested','revision',rev); END $$;
GRANT EXECUTE ON FUNCTION public.store_income_category_suggestion(uuid,uuid,uuid,text,text) TO service_role;
CREATE OR REPLACE FUNCTION public.guard_income_category_review() RETURNS trigger LANGUAGE plpgsql SET search_path = public, pg_temp AS $$ BEGIN IF TG_OP = 'UPDATE' THEN IF OLD.verification_status <> 'pending' AND (NEW.category_id IS DISTINCT FROM OLD.category_id OR NEW.suggested_category_id IS DISTINCT FROM OLD.suggested_category_id OR NEW.suggestion_revision IS DISTINCT FROM OLD.suggestion_revision OR NEW.category_confirmed_at IS DISTINCT FROM OLD.category_confirmed_at) THEN RAISE EXCEPTION 'income_category_locked' USING ERRCODE='23514'; END IF; IF NEW.verification_status = 'verified' AND OLD.verification_status = 'pending' AND (OLD.category_confirmed_at IS NULL OR (OLD.suggestion_revision IS NOT NULL AND OLD.category_confirmed_at < OLD.suggested_at)) THEN RAISE EXCEPTION 'income_category_review_required' USING ERRCODE='23514'; END IF; END IF; RETURN NEW; END $$;